import re

def parse_g(raw):
    d = {}
    items = re.findall(r'(\d+)\)\s*([A-D*-])', raw)
    for q, ans in items:
        d[int(q)] = ans
    return d

tests = {
    'AD_T1': parse_g(t_ad1),
    'AD_T2': parse_g(t_ad2),
    'AD_T3': parse_g(t_ad3),
    'CG_T1': parse_g(t_cg1),
    'CG_T2': parse_g(t_cg2),
    'CG_T3': parse_g(t_cg3),
}

samples = [
    (3, 'B'), (5, 'B'), (7, 'D'), (11, 'A'), (14, 'A'),
    (20, 'D'), (25, 'C'), (38, 'A'), (50, 'B'), (51, 'B'),
    (67, 'D'), (70, 'A'), (72, 'A'), (73, 'B'), (81, 'A'), (100, 'D')
]

for name, gb in tests.items():
    matches = sum(1 for q, ans in samples if gb.get(q) == ans)
    print(f"{name}: {matches}/{len(samples)} matches ({matches/len(samples)*100:.1f}%)")

